  "span_id": "cnc_1_t0_cause",
  "span": "the allocation of low cost ( RDP ) houses at Marikana West Extension 2",
  "structure": {
    "components": [
      {
        "role": "Action",
        "value": "allocation",
        "attributes": []
      },
      {
        "role": "Theme",
        "value": "houses",
        "attributes": [
          {
            "role": "Cost",
            "value": "low cost"
          },
          {
            "role": "Type",
            "value": "RDP"
          }
        ]
      },
      {
        "role": "Location",
        "value": "Marikana West Extension 2",
        "attributes": []
      }
    ]
  },
  "indexed_units": [
    {
      "id": "n0",
      "kind": "node",
      "path": "c0",
      "role": "Action",
      "value": "allocation"
    },
    {
      "id": "n1",
      "kind": "node",
      "path": "c1",
      "role": "Theme",
      "value": "houses"
    },
    {
      "id": "a0",
      "kind": "attribute",
      "path": "c1.attr0",
      "parent": {
        "id": "n1",
        "role": "Theme",
        "value": "houses"
      },
      "role": "Cost",
      "value": "low cost"
    },
    {
      "id": "a1",
      "kind": "attribute",
      "path": "c1.attr1",
      "parent": {
        "id": "n1",
        "role": "Theme",
        "value": "houses"
      },
      "role": "Type",
      "value": "RDP"
    },
    {
      "id": "n2",
      "kind": "node",
      "path": "c2",
      "role": "Location",
      "value": "Marikana West Extension 2"
    }
  ]
}

Output schema:
